// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.agent.diimport android.content.Contextimport com.roshan.persona.agent.automation.AccessibilityAutomationProviderimport com.roshan.persona.agent.automation.AutomationMethodDetectorimport com.roshan.persona.agent.automation.AutomationProviderimport com.roshan.persona.agent.permission.AccessibilityPermissionManagerimport dagger.Moduleimport dagger.Providesimport dagger.hilt.InstallInimport dagger.hilt.android.qualifiers.ApplicationContextimport dagger.hilt.components.SingletonComponentimport javax.inject.Singleton/** * NOUS — Agent Hilt Module (Module 9 v1 — Step 9.8, P1 fix). * * Previously this file was mentioned in KDoc comments across the module but * **never created** — meaning `BankingAppGuard`, `AccessibilityAutomationProvider`, * `AutomationMethodDetector`, and `AccessibilityPermissionManager` had no Hilt * bindings, so any Hilt consumer that injected them would fail at compile time. * * This module wires every Module 9 class that needs to be injectable. Things * instantiated by the Android framework (`NousAccessibilityService`, * `NousNotificationListenerService`) are NOT provided here — they live in * their respective static registries (`AccessibilityServiceRegistry`, * `NousNotificationListenerService.Companion.activeInstance`). * * ## Provided bindings * * | Type | Bound via | Notes | * |------|-----------|-------| * | `BankingAppGuard` | `@Singleton @Inject constructor()` (auto) | 21-package blacklist — no explicit `@Provides` to avoid duplicate binding | * | [AutomationProvider] | `@Provides` in this module → [AccessibilityAutomationProvider] | Tier-1 universal provider | * | [AccessibilityAutomationProvider] | `@Singleton @Inject constructor()` (auto) | Concrete Tier-1 provider | * | [AutomationMethodDetector] | `@Provides` in this module | Needs `@ApplicationContext` | * | [AccessibilityPermissionManager] | `@Provides` in this module | Needs `@ApplicationContext`; 24h cooldown backed by EncryptedSharedPreferences | * * ## Not provided here (intentional) * *  - `NousAccessibilityService` — instantiated by Android framework, accessed via *    `AccessibilityServiceRegistry.getInstance()`. *  - `NousNotificationListenerService` — same pattern (framework-instantiated). *  - `UiTreeSnapshot` — pure data class with a `from()` factory; no DI needed. *  - `NousAccessibilityServiceInterface` — already bound by `:feature:system`'s *    `SystemModule.provideAccessibilityService()` to `NoopAccessibilityService`. *    A future Step 9.8.1 can use Hilt's `@Module(replaces = SystemModule::class)` *    pattern (or simpler: remove the SystemModule binding) to override that *    with `NousAccessibilityServiceInterfaceImpl`. Not done here to avoid a *    duplicate-binding compile error in this P1 fix. * * @see <a href="docs/strategy/module-9-agent-strategy-v1.md">§Step 9.8: AgentModule</a> */@Module@InstallIn(SingletonComponent::class)object AgentModule {    // ─── Guards ──────────────────────────────────────────────────────────────    // NOTE: BankingAppGuard has `@Singleton @Inject constructor()` — Hilt    // auto-provides it. We do NOT add an explicit `@Provides` here, because    // doing so would create a duplicate-binding error.    // ─── Automation ──────────────────────────────────────────────────────────    /**     * Bind [AccessibilityAutomationProvider] as the canonical [AutomationProvider].     *     * Tier-1 implementation — universal fallback for devices that don't have     * Wireless Debugging enabled. When LADB lands (Step 9.4), a future     * `LadbAutomationProvider` can be qualified with `@Named("ladb")` and the     * `AutomationEngine` (Step 9.5) will choose between them at runtime.     *     * Note: `AccessibilityAutomationProvider` itself is auto-provided by Hilt     * via its `@Inject constructor()` — we only need to bind it to the     * [AutomationProvider] interface here.     */    @Provides    @Singleton    fun provideAutomationProvider(impl: AccessibilityAutomationProvider): AutomationProvider = impl    /**     * Provide [AutomationMethodDetector] — needs an `@ApplicationContext` to     * read `Settings.Global.ADB_WIFI_ENABLED` and     * `Settings.Secure.ENABLED_ACCESSIBILITY_SERVICES`.     */    @Provides    @Singleton    fun provideAutomationMethodDetector(        @ApplicationContext context: Context,    ): AutomationMethodDetector = AutomationMethodDetector(context)    // ─── Permissions ─────────────────────────────────────────────────────────    /**     * Provide [AccessibilityPermissionManager] — needs `@ApplicationContext`     * to read `Settings.Secure` + initialise `EncryptedSharedPreferences`     * for the 24h cooldown timer (Step 9.1 + P2 fix).     */    @Provides    @Singleton    fun provideAccessibilityPermissionManager(        @ApplicationContext context: Context,    ): AccessibilityPermissionManager = AccessibilityPermissionManager(context)}